design\activity\card__5cdae748-9597-4d29-8dc0-3d4b5df3aa7f.json:152:          "content": "import type { TriggerFn } from '@lexical/react/LexicalTypeaheadMenuPlugin'\n\nconst PLACEHOLDER_TRIGGER_PATTERN = /\\{\\{([^{}\\s]*)$/u\n\nexport const matchPlaceholderTrigger: TriggerFn = (text) => {\n    const match = PLACEHOLDER_TRIGGER_PATTERN.exec(text)\n    if (!match) return null\n\n    return {\n        leadOffset: match.index,\n        matchingString: match[1],\n        replaceableString: match[0],\n    }\n}\n\r\n",
