design\activity\card__5cdae748-9597-4d29-8dc0-3d4b5df3aa7f.json:2799:          "content": "import { describe, expect, it, vi } from 'vitest'\nimport { LinkNode, $isLinkNode } from '@lexical/link'\nimport { $createParagraphNode, $createTextNode, $getRoot, createEditor, type TextNode } from 'lexical'\nimport { MarkdownFileSearchOption } from './markdown_file_search_option'\nimport { replaceFileSearchQuery } from './markdown_file_search_typeahead_plugin'\n\ndescribe('replaceFileSearchQuery', () => {\n    it('replaces the query, restores the caret, and closes the menu', () => {\n        const closeMenu = vi.fn()\n        const editor = createEditor({ nodes: [LinkNode] })\n\n        editor.update(() => {\n            const textNode = $createTextNode('@F_108')\n            $getRoot().append($createParagraphNode().append(textNode))\n            replaceFileSearchQuery(new MarkdownFileSearchOption('design/F_108.md'), textNode, closeMenu)\n        }, { discrete: true })\n\n        editor.getEditorState().read(() => {\n            const linkNode = $getRoot().getFirstDescendant()\n            expect($isLinkNode(linkNode)).toBe(true)\n            if (!$isLinkNode(linkNode)) throw new Error('Expected selected repository file to create a link node')\n\n            expect(linkNode.getTextContent()).toBe('F_108.md')\n            expect(linkNode.getURL()).toBe('design/F_108.md')\n        })\n        expect(closeMenu).toHaveBeenCalledOnce()\n    })\n\n    it('leaves the menu open when the query node is unavailable', () => {\n        const closeMenu = vi.fn()\n\n        replaceFileSearchQuery(new MarkdownFileSearchOption('design/F_108.md'), null, closeMenu)\n\n        expect(closeMenu).not.toHaveBeenCalled()\n    })\n})\n\r\n/** Return filename portion of a repository-relative path. */\nexport function repositoryFileName(repositoryPath: string) {\n    const segments = repositoryPath.split('/')\n\n    return segments.at(-1) ?? ''\n}\n\n/** Match a repository path against a case-insensitive file-search query. */\nexport function repositoryFileMatchesQuery(repositoryPath: string, query: string) {\n    return repositoryPath.toLocaleLowerCase().includes(query.toLocaleLowerCase())\n}\n\r\n",
design\activity\card__5cdae748-9597-4d29-8dc0-3d4b5df3aa7f.json:2805:          "output": "import { describe, expect, it, vi } from 'vitest'\nimport { LinkNode, $isLinkNode } from '@lexical/link'\nimport { $createParagraphNode, $createTextNode, $getRoot, createEditor, type TextNode } from 'lexical'\nimport { MarkdownFileSearchOption } from './markdown_file_search_option'\nimport { replaceFileSearchQuery } from './markdown_file_search_typeahead_plugin'\n\ndescribe('replaceFileSearchQuery', () => {\n    it('replaces the query, restores the caret, and closes the menu', () => {\n        const closeMenu = vi.fn()\n        const editor = createEditor({ nodes: [LinkNode] })\n\n        editor.update(() => {\n            const textNode = $createTextNode('@F_108')\n            $getRoot().append($createParagraphNode().append(textNode))\n            replaceFileSearchQuery(new MarkdownFileSearchOption('design/F_108.md'), textNode, closeMenu)\n        }, { discrete: true })\n\n        editor.getEditorState().read(() => {\n            const linkNode = $getRoot().getFirstDescendant()\n            expect($isLinkNode(linkNode)).toBe(true)\n            if (!$isLinkNode(linkNode)) throw new Error('Expected selected repository file to create a link node')\n\n            expect(linkNode.getTextContent()).toBe('F_108.md')\n            expect(linkNode.getURL()).toBe('design/F_108.md')\n        })\n        expect(closeMenu).toHaveBeenCalledOnce()\n    })\n\n    it('leaves the menu open when the query node is unavailable', () => {\n        const closeMenu = vi.fn()\n\n        replaceFileSearchQuery(new MarkdownFileSearchOption('design/F_108.md'), null, closeMenu)\n\n        expect(closeMenu).not.toHaveBeenCalled()\n    })\n})\n\r\n/** Return filename portion of a repository-relative path. */\nexport function repositoryFileName(repositoryPath: string) {\n    const segments = repositoryPath.split('/')\n\n    return segments.at(-1) ?? ''\n}\n\n/** Match a repository path against a case-insensitive file-search query. */\nexport function repositoryFileMatchesQuery(repositoryPath: string, query: string) {\n    return repositoryPath.toLocaleLowerCase().includes(query.toLocaleLowerCase())\n}\n\r\n",
